BEGIN;

DO $guard$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.baseset_materials
    WHERE id = 9007180196267238 AND code IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_11_MAT'
  ) THEN
    RAISE EXCEPTION 'fixture material id % is owned by another record', 9007180196267238;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.rm_formulas
    WHERE id = 9007180196267239 AND formual_code IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_11_FORM'
  ) THEN
    RAISE EXCEPTION 'fixture formula id % is owned by another record', 9007180196267239;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.wom_produce_tasks
    WHERE id = 9007180196267240
      AND (table_no IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_11_TASK_TN'
           OR produce_batch_num IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_11_BATCH')
  ) THEN
    RAISE EXCEPTION 'fixture WOM task id % is owned by another record', 9007180196267240;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.wom_wait_put_records
    WHERE id = 9007180196267241 AND task_id IS DISTINCT FROM 9007180196267240
  ) THEN
    RAISE EXCEPTION 'fixture WOM wait id % is owned by another task', 9007180196267241;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.wfm_task_pending
    WHERE id = 9007180196267242
      AND (table_info_id IS DISTINCT FROM 9007180196267240
           OR table_no IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_11_TASK_TN')
  ) THEN
    RAISE EXCEPTION 'fixture workflow pending id % is owned by another task', 9007180196267242;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.wom_output_details d
    LEFT JOIN public.wom_proc_reports r ON r.id = d.head_id
    WHERE d.id = 9007180196267243
      AND r.task_id IS DISTINCT FROM 9007180196267240
  ) THEN
    RAISE EXCEPTION 'fixture output detail id % is owned by another task', 9007180196267243;
  END IF;
END
$guard$;

DELETE FROM public.wom_mat_outpt_records WHERE out_mat_detail_id = 9007180196267243;
DELETE FROM public.wom_output_details
 WHERE id = 9007180196267243
    OR head_id IN (SELECT id FROM public.wom_proc_reports WHERE task_id = 9007180196267240);
DELETE FROM public.wom_task_act_itemss WHERE produce_batch_num = 'ADP_E2E_20260727_MES_FULL_CLOSED_11_BATCH';
DELETE FROM public.wom_acti_exelogs WHERE task_id = 9007180196267240;
DELETE FROM public.wom_process_exelogs WHERE task_id = 9007180196267240;
DELETE FROM public.wom_task_actives WHERE task_id = 9007180196267240;
DELETE FROM public.wom_task_processes WHERE task_id = 9007180196267240;
DELETE FROM public.wom_produce_task_exelog WHERE task_id = 9007180196267240;
DELETE FROM public.wom_proc_reports WHERE task_id = 9007180196267240;
DELETE FROM public.wf_deal_info WHERE table_info_id = 9007180196267240;
DELETE FROM public.wfm_task_pending WHERE id = 9007180196267242 OR table_info_id = 9007180196267240;
DELETE FROM public.wom_wait_put_records WHERE id = 9007180196267241 OR task_id = 9007180196267240;
DELETE FROM public.wom_produce_tasks WHERE id = 9007180196267240;
DELETE FROM public.rm_formulas WHERE id = 9007180196267239;
DELETE FROM public.baseset_materials WHERE id = 9007180196267238;

COMMIT;
SELECT 'cleanup',
       (SELECT count(*) FROM public.wom_produce_tasks WHERE id = 9007180196267240),
       (SELECT count(*) FROM public.wom_wait_put_records WHERE task_id = 9007180196267240),
       (SELECT count(*) FROM public.rm_formulas WHERE id = 9007180196267239),
       (SELECT count(*) FROM public.baseset_materials WHERE id = 9007180196267238);

